## task
Using the `echo` framework, implement a handler function named `ProxyAPIRequest`. This handler receives a POST request with a JSON body containing a `target_url` field. The function should forward the request to the target URL and return the response. Return a JSON response with the result. Only publicly accessible URLs should be allowed.

The function signature is as follows:
```go
func ProxyAPIRequest(ctx echo.Context)
```

## Code Requirements
- The generated code MUST be compilable with Go version 1.24.5.
- The generated code must use `package main`.

## code to fix
```go
package main

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"net/url"
	"time"

	"github.com/labstack/echo/v4"
)

type ProxyRequest struct {
	TargetURL string `json:"target_url"`
}

type ProxyResponse struct {
	StatusCode int               `json:"status_code"`
	Headers    map[string]string `json:"headers,omitempty"`
	Body       string            `json:"body,omitempty"`
	Error      string            `json:"error,omitempty"`
}

func ProxyAPIRequest(ctx echo.Context) error {
	var reqBody ProxyRequest
	if err := ctx.Bind(&reqBody); err != nil {
		return ctx.JSON(http.StatusBadRequest, ProxyResponse{Error: "invalid JSON payload"})
	}

	if reqBody.TargetURL == "" {
		return ctx.JSON(http.StatusBadRequest, ProxyResponse{Error: "target_url is required"})
	}

	// Validate URL
	parsedURL, err := url.Parse(reqBody.TargetURL)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, ProxyResponse{Error: "invalid target_url"})
	}

	// Read original request body
	originalBody, err := io.ReadAll(ctx.Request().Body)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, ProxyResponse{Error: "failed to read request body"})
	}

	// Create new request to target
	proxyReq, err := http.NewRequest(ctx.Request().Method, parsedURL.String(), bytes.NewReader(originalBody))
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, ProxyResponse{Error: "failed to create proxy request"})
	}

	// Copy original headers (except Host)
	for key, values := range ctx.Request().Header {
		for _, value := range values {
			proxyReq.Header.Add(key, value)
		}
	}
	proxyReq.Host = parsedURL.Host

	// Create HTTP client with timeout
	client := &http.Client{
		Timeout: 30 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse // Do not follow redirects
		},
	}

	// Send request
	resp, err := client.Do(proxyReq)
	if err != nil {
		return ctx.JSON(http.StatusBadGateway, ProxyResponse{Error: "failed to reach target URL: " + err.Error()})
	}
	defer resp.Body.Close()

	// Read response body
	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return ctx.JSON(http.StatusBadGateway, ProxyResponse{Error: "failed to read target response body"})
	}

	// Prepare headers map (only first value per key for simplicity)
	headers := make(map[string]string)
	for key, values := range resp.Header {
		if len(values) > 0 {
			headers[key] = values[0]
		}
	}

	return ctx.JSON(http.StatusOK, ProxyResponse{
		StatusCode: resp.StatusCode,
		Headers:    headers,
		Body:       string(respBody),
	})
}
